def pre(n, out):
    if n:
        out.append(n['v'])
        pre(n['l'], out)
        pre(n['r'], out)
t = {'v': 1, 'l': {'v': 2, 'l': None, 'r': None},
     'r': {'v': 3, 'l': None, 'r': None}}
out = []
pre(t, out)
print(out)

def leaves(n):
    if n is None: return 0
    if not n['l'] and not n['r']: return 1
    return leaves(n['l']) + leaves(n['r'])
t = {'v': 1,
     'l': {'v': 2, 'l': None, 'r': None},
     'r': {'v': 3, 'l': {'v': 4, 'l': None, 'r': None}, 'r': None}}
print(leaves(t))

def total(n):
    if n is None:
        return 0
    return n['v'] + total(n['l']) + total(n['r'])
t = {'v': 1,
     'l': {'v': 2, 'l': None, 'r': None},
     'r': {'v': 3, 'l': None, 'r': {'v': 4, 'l': None, 'r': None}}}
print(total(t))
